cat > src/board.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { BoardError, createBoard, type BoardErrorCode, type ColumnConfig } from "./board";

test("board errors carry a code", () => {
  const error = new BoardError("WIP_LIMIT", "Column Review is full");
  expect(error).toBeInstanceOf(Error);
  expect(error.code).toBe("WIP_LIMIT");
});

function setup(columns: ColumnConfig[] = [{ name: "Backlog" }, { name: "Doing" }, { name: "Review" }, { name: "Done" }]) {
  const clock = { t: 1_000 };
  const board = createBoard({ columns, now: () => clock.t });
  return { board, clock };
}

function codeOf(action: () => unknown): BoardErrorCode | "no error" | "other error" {
  try {
    action();
  } catch (error) {
    return error instanceof BoardError ? error.code : "other error";
  }
  return "no error";
}

test("addCard returns C1 and the card is listed in the first column", () => {
  const { board } = setup();
  expect(board.addCard("Fix login")).toBe("C1");
  expect(board.cardsIn("Backlog")).toEqual(["C1"]);
});
EOF
.claude/skills/tdd-deep-modules/scripts/tdd-step red "addCard returns C1 in first column" 2>&1 | tail -5

cat >> src/board.test.ts <<'EOF'

test("adding to a full first column is rejected with WIP_LIMIT", () => {
  const { board } = setup([{ name: "Backlog", wipLimit: 2 }, { name: "Done" }]);
  board.addCard("a");
  board.addCard("b");
  expect(codeOf(() => board.addCard("c"))).toBe("WIP_LIMIT");
  expect(board.cardsIn("Backlog")).toEqual(["C1", "C2"]);
});
