python3 - <<'EOF'
p='src/board.ts'; s=open(p).read()
start=s.index('export function createBoard')
s=s[:start]+'''export function createBoard(options: BoardOptions): Board {
  const columns = new Map<string, string[]>(options.columns.map((c) => [c.name, []]));
  const first = columns.get(options.columns[0].name)!;
  let count = 0;
  return {
    addCard(title) {
      if (title.trim() === "") throw new BoardError("EMPTY_TITLE", "Title is empty");
      const limit = options.columns[0].wipLimit;
      if (limit !== undefined && first.length >= limit) throw new BoardError("WIP_LIMIT", "First column is full");
      const id = `C${++count}`;
      first.push(id);
      return id;
    },
    move(cardId, toColumn) {
      for (const list of columns.values()) {
        const i = list.indexOf(cardId);
        if (i >= 0) list.splice(i, 1);
      }
      columns.get(toColumn)!.push(cardId);
    },
    block() {},
    unblock() {},
    cardsIn(column) {
      return [...columns.get(column)!];
    },
    cycleTime() {
      return null;
    },
  };
}
'''
open(p,'w').write(s)
EOF
